  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    # Find root
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    # Determine non-removable and removable nodes
    non_removable_ids = {n['id'] for n in nodes if not n['removable']}
    removable_ids = {n['id'] for n in nodes if n['removable']}
    # Keep all non-removable
    kept = set(non_removable_ids)
    # For each required symbol, ensure at least one node with that symbol is kept
    # If there is a non-removable node with that symbol, it's already kept.
    # Otherwise, we must keep one removable node with that symbol (the one with max utility).
    for sym in required_symbols:
        sym_nodes = [n for n in nodes if n['symbol'] == sym]
        if any(n['id'] in non_removable_ids for n in sym_nodes):
            continue  # already satisfied by non-removable
        # need to pick a removable node with this symbol
        candidates = [n for n in sym_nodes if n['id'] in removable_ids]
        if candidates:
            best = max(candidates, key=lambda x: x['utility'])
            kept.add(best['id'])
    # Return list of kept node ids (sorted for determinism)
    result = sorted(kept)
    return result"
